From 69562c216aa20552b0d5cce16252f811c82fc969 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:39:39 +0100
Subject: [PATCH] applets/notifications: Keep the file menu on screen when the
 notification moves

The file menu moved along with its notification but was never placed
again, so it ran off the bottom of the screen when the notification slid
down. Now it is moved with it, so the compositor constrains it again.

BUG: 486595
---
 applets/notifications/filemenu.cpp | 22 ++++++++++++++++++++++
 1 file changed, 22 insertions(+)

diff --git a/applets/notifications/filemenu.cpp b/applets/notifications/filemenu.cpp
index 19396e79fb..af1345ccdd 100644
--- a/applets/notifications/filemenu.cpp
+++ b/applets/notifications/filemenu.cpp
@@ -14,6 +14,8 @@
 #include <QQuickWindow>
 #include <QTimer>

+#include <memory>
+
 #include <KConfigGroup>
 #include <KFileItemActions>
 #include <KFileItemListProperties>
@@ -240,10 +242,30 @@ void FileMenu::open(int x, int y)
         window->setProperty("_q_waylandPopupConstraintAdjustment", 1u | 8u); // slide_x | flip_y
     } else {
         pos = m_visualParent->mapToGlobal(QPointF(x, y)).toPoint();
+
+        // Anchor to the click position in the notification, so the menu can be placed again when that moves.
+        window->setProperty("_q_waylandPopupAnchorRect", QRect{m_visualParent->mapToScene(QPointF(x, y)).toPoint(), QSize{1, 1}});
+        window->setProperty("_q_waylandPopupAnchor", int(Qt::TopEdge | Qt::LeftEdge));
+        window->setProperty("_q_waylandPopupGravity", int(Qt::BottomEdge | Qt::RightEdge));
+        window->setProperty("_q_waylandPopupConstraintAdjustment", 1u | 2u | 8u); // slide_x | slide_y | flip_y
     }

     menu->popup(pos);

+    // The menu moves along with the notification but isn't placed again, so it can end up off-screen when the
+    // notification slides down. Moving it makes Qt send a new positioner, so the compositor constrains it again.
+    QWindow *parentWindow = m_visualParent->window();
+    auto parentPos = std::make_shared<QPoint>(parentWindow->position());
+    auto followParent = [menu, parentWindow, parentPos] {
+        const QPoint delta = parentWindow->position() - *parentPos;
+        *parentPos = parentWindow->position();
+        if (!delta.isNull() && menu->isVisible()) {
+            menu->move(menu->pos() + delta);
+        }
+    };
+    connect(parentWindow, &QWindow::xChanged, menu, followParent);
+    connect(parentWindow, &QWindow::yChanged, menu, followParent);
+
     m_visible = true;
     Q_EMIT visibleChanged();
 }
